def xor_encode_multi(data: bytes, key: bytes) -> bytes:
    return bytes([b ^ key[i % len(key)] for i, b in enumerate(data)])

def xor_decode_multi(data: bytes, key: bytes) -> bytes:
    return bytes([b ^ key[i % len(key)] for i, b in enumerate(data)])

original = b'\xb8\x01\x00\x00\x00\xcd\x80'
key = b'KEY'
encoded = xor_encode_multi(original, key)
decoded = xor_decode_multi(encoded, key)

print(f'Original: {original.hex()}')
print(f'Encoded:  {encoded.hex()}')
print(f'Decoded:  {decoded.hex()}')
assert original == decoded

